 67	    expect(di.curve?.anchor.document).toBe("bcb_sgs_cdi_diario.json");
 68	    // Q3 has no payment: the whole quarter accrues and is carried.
 69	    const spread = (days: number) => d(accrualFactorAtPrecision({annualRate: "0.0065", businessDays: days, decimals: 9, mode: "round"}).value);
 70	    const f63 = r8(businessDayAccrual(annualCdi, 63).value).plus(1).times(spread(63).plus(1)).minus(1).toDecimalPlaces(9);
