/bin/bash -lc "node <<'NODE'
const D=require('decimal.js');D.set({precision:50,rounding:D.ROUND_HALF_UP});
const d=x=>new D(x); const dp=(x,n,mode=D.ROUND_HALF_UP)=>d(x).toDecimalPlaces(n,mode); const out=x=>dp(x,8).toFixed();
const daily=d('0.0005166'); const annual=out(daily.plus(1).pow(252).minus(1));
function annualFactor(rate,days,n=9){return dp(d(rate).plus(1).pow(d(days).div(252)).minus(1),n)}
function diSpread(days){const di=dp(d(annual).plus(1).pow(d(days).div(252)).minus(1),8);const sp=annualFactor('0.0065',days,9);return dp(di.plus(1).times(sp.plus(1)).minus(1),9)}
function diPct(days){const raw=d(annual).plus(1).pow(d(1).div(252)).minus(1).times('1.04').plus(1).pow(days).minus(1);return dp(dp(raw,16,D.ROUND_DOWN),9)}
function fixed(days){return dp(d('1.1415').pow(d(days).div(252)).minus(1),9)}
function schedule(id,p,fac,eventsByPeriod){let principal=d(p),carried=d(0), cash=d(0);let rows=[];for(let qi=0;qi<4;qi++){let used=0,paid=d(0),accr=d(0),pf=d(1);for(const ev of eventsByPeriod[qi]||[]){const days=ev-used,f=fac(days),a=dp(principal.plus(carried).times(f),8,D.ROUND_DOWN);accr=accr.plus(a);carried=carried.plus(a);pf=pf.times(f.plus(1));used=ev;paid=paid.plus(carried);carried=d(0)}const f=fac(63-used),a=dp(principal.plus(carried).times(f),8,D.ROUND_DOWN);accr=accr.plus(a);carried=carried.plus(a);pf=pf.times(f.plus(1));cash=cash.plus(paid);rows.push({period:['2026Q3','2026Q4','2027Q1','2027Q2'][qi],coupon_factor:out(pf.minus(1)),coupon_accrued:out(accr),coupon_paid:out(paid),coupon_carried:out(carried),closing_principal:out(principal)});}return{id,rows,total_cash:out(cash)}}
const s13=schedule('deb-13-1','304160',diSpread,[[],[53],[],[52]]);
const s14=schedule('deb-14-1','411643',diPct,[[9],[],[10],[]]);
const s15=schedule('deb-15-2','406349',fixed,[[],[53],[],[52]]);
const ss=[s13,s14,s15];
console.log(JSON.stringify({daily,annual,factors:{diSpread:{f10:diSpread(10).toFixed(),f11:diSpread(11).toFixed(),f52:diSpread(52).toFixed(),f53:diSpread(53).toFixed(),f63:diSpread(63).toFixed(),spread63:annualFactor('0.0065',63,9).toFixed()},diPct:{f9:diPct(9).toFixed(),f10:diPct(10).toFixed(),f53:diPct(53).toFixed(),f54:diPct(54).toFixed(),f63:diPct(63).toFixed()},fixed:{f10:fixed(10).toFixed(),f11:fixed(11).toFixed(),f52:fixed(52).toFixed(),f53:fixed(53).toFixed(),f63:fixed(63).toFixed()}},ss,aggregate:{by_period:[0,1,2,3].map(i=>({period:ss[0].rows[i].period,cash_interest:out(ss.reduce((t,s)=>t.plus(s.rows[i].coupon_paid),d(0)))})),by_indexer:{CDI:out(d(s13.total_cash).plus(s14.total_cash)),fixed:s15.total_cash},opening:out(d(304160).plus(411643).plus(406349)),coverage:out(d(1122152).div(5670186))}},null,2));
NODE"

