 45	  /** Business days of the period, from the calendar the base cites (holidays included). */
 46	  businessDays: z.number().int().nonnegative(),
 47	  /** The calendar the count comes from. */
 48	  anchor: anchorSchema,
 49	}).strict();
 50	
 51	export const curveSchema = z.object({
 52	  id: nonEmpty,
 53	  kind: z.enum(["CDI", "IPCA"]),
 54	  /** Annual effective rate per period as a decimal, or the daily rate the source publishes (annualized by the executor as (1 + daily)^252 - 1). One of the two. */
 55	  annualRateByPeriod: z.record(nonEmpty, rate).nullable().default(null),
 56	  dailyRateByPeriod: z.record(nonEmpty, rate).nullable().default(null),
 57	  /** IPCA only: monthly variation by calendar month (YYYY-MM) as a decimal, for the anniversary updates. */
 58	  monthlyRateByMonth: z.record(isoMonth, rate).nullable().default(null),
 59	  source: z.object({title: nonEmpty, url: z.string().optional(), asOf: isoDate, anchor: anchorSchema}).strict(),
 60	}).strict();
 61	
 62	export const seriesRemunerationSchema = z.discriminatedUnion("type", [
 63	  z.object({type: z.literal("spread_over_index"), spreadPerYear: rate}).strict(),
 64	  z.object({type: z.literal("percent_of_index"), percentOfIndex: nonNegative}).strict(),
 65	  z.object({type: z.literal("fixed"), ratePerYear: rate}).strict(),
 66	]);
 67	
 68	/** Rounding the indenture writes, layer by layer: the index factor, the spread factor, their product (Fator Juros), the daily accumulation and the amount. */
 69	const layerSchema = z.object({decimals: z.number().int().min(2).max(16), mode: z.enum(["round", "truncate"])}).strict();
 70	export const roundingSchema = z.object({
 71	  indexFactor: layerSchema,
 72	  spreadFactor: layerSchema,
 73	  interestFactor: layerSchema,
 74	  dailyAccumulation: layerSchema,
 75	  amount: layerSchema,
 76	  anchor: anchorSchema,
 77	}).strict();
 78	
 79	export const seriesInputSchema = z.object({
 80	  id: nonEmpty,
 81	  label: nonEmpty,
 82	  /** The nominal at the reference date and where it comes from; a ledger balance including accrued interest is not a nominal. */
 83	  openingPrincipal: z.object({value: nonNegative, basis: z.enum(["unit_value_x_quantity", "unit_value_x_quantity_updated", "trustee_report_nominal", "ledger_balance_including_accrued"]), anchor: anchorSchema}).strict(),
 84	  /** Remuneration accrued at the reference date since the last payment; null when the base does not hold it. */
 85	  openingAccrued: z.object({value: nonNegative, anchor: anchorSchema}).strict().nullable(),
 86	  indexer: z.enum(["CDI", "IPCA", "fixed", "unknown"]),
 87	  remuneration: seriesRemunerationSchema.nullable(),
 88	  /** Coupon payment dates with the business days from the start of the period that holds them, from the calendar the base cites; positions inside a period must advance. */
 89	  couponDates: z.array(z.object({date: isoDate, businessDaysFromPeriodStart: z.number().int().nonnegative()}).strict()).nullable(),
 90	  /** Scheduled principal payments with their business-day position inside the period that holds them; null when the base has no amortization schedule for the series. */
 91	  amortization: z.array(z.object({date: isoDate, amount: nonNegative, businessDaysFromPeriodStart: z.number().int().nonnegative()}).strict()).nullable(),
 92	  /** IPCA only: how the update is treated (capitalized or paid); null when the indenture is not in the base, in which case both are projected. */
 93	  indexationTreatment: z.enum(["capitalized_principal", "cash_paid"]).nullable(),
 94	  /** IPCA only: the anniversary day and the lag in months the indenture writes for the index number, and, per period, the business days elapsed since the last anniversary (dup) over the business days of that anniversary month (dut) for the pro rata at the period end; null when the base does not give the counts. */
 95	  indexation: z.object({anniversaryDay: z.number().int().min(1).max(31), lagMonths: z.number().int().min(0).max(3), /** The anniversary dates the base lists (the business day before the calendar anniversary, as the indenture writes); null when not in the base, in which case calendar days are used and declared. */ anniversaryDates: z.array(isoDate).nullable(), proRataByPeriod: z.record(nonEmpty, z.object({dup: z.number().int().nonnegative(), dut: z.number().int().positive()}).strict()).nullable(), anchor: anchorSchema}).strict().nullable(),
 96	  rounding: roundingSchema.nullable(),
 97	  curveId: nonEmpty.nullable(),
 98	  anchors: z.object({balance: anchorSchema, terms: anchorSchema.nullable(), payments: anchorSchema.nullable(), amortization: anchorSchema.nullable()}).strict(),
 99	}).strict();
100	
101	const UNIT_WORDS: Record<z.infer<typeof unitSchema>, RegExp> = {"BRL": /\b(R\$|reais|BRL)\b(?!\s*(mil|milh))/i, "BRL thousand": /\b(mil|thousand)\b/i, "BRL million": /\b(milh[õo]es|million)\b/i, "USD": /\bUSD\b(?!\s*(mil|thousand))/i, "USD thousand": /\bUSD\b.*\b(mil|thousand)\b/i};
102	
103	export const interestScheduleInputSchema = z.object({
104	  referenceDate: isoDate,
105	  unit: unitSchema,
106	  /** Where the source states the unit; its note must name it, so a relabelled scale is refused. */
107	  unitAnchor: anchorSchema.extend({note: nonEmpty}),
108	  periods: z.array(projectionPeriodSchema).min(1),
109	  curves: z.array(curveSchema).default([]),
110	  series: z.array(seriesInputSchema).min(1),
111	  /** The ledger's control: the series it holds and their nominal total, so omitted series are named and the projection's coverage is measured. */
112	  ledgerControl: z.object({seriesIds: z.array(nonEmpty), grossDebt: nonNegative, anchor: anchorSchema}).strict().nullable().default(null),
113	  /** The finance expense of the last closed period, to bridge against; null when not in the base. */
114	  accountingInterestLastPeriod: z.object({value: z.string().regex(/^-?\d+(\.\d+)?$/), periodId: nonEmpty, anchor: anchorSchema}).strict().nullable().default(null),
115	}).strict().superRefine((input, context) => {
116	  if (!UNIT_WORDS[input.unit].test(input.unitAnchor.note)) context.addIssue({code: "custom", path: ["unitAnchor"], message: `the unit anchor's note does not name the unit ${input.unit}; a relabelled scale is refused`});
117	  const periodIds = new Set<string>();
