132	  });
133	  const seriesIds = new Set<string>();
134	  input.series.forEach((series, index) => {
135	    if (seriesIds.has(series.id)) context.addIssue({code: "custom", path: ["series"], message: `duplicate series ${series.id}`});
136	    seriesIds.add(series.id);
137	    const dates = new Set<string>();
138	    const lastPosition = new Map<string, number>();
139	    for (const coupon of [...(series.couponDates ?? [])].sort((a, b) => compare(a.date, b.date))) {
140	      if (dates.has(coupon.date)) context.addIssue({code: "custom", path: ["series", index, "couponDates"], message: `${series.id}: coupon date ${coupon.date} listed twice`});
141	      dates.add(coupon.date);
142	      const period = sorted.find((entry) => coupon.date > entry.start && coupon.date <= entry.end);
143	      if (period && coupon.businessDaysFromPeriodStart > period.businessDays) context.addIssue({code: "custom", path: ["series", index, "couponDates"], message: `${series.id}: coupon ${coupon.date} claims ${coupon.businessDaysFromPeriodStart} business days inside ${period.id}, which has ${period.businessDays}`});
