145	        const previous = lastPosition.get(period.id);
146	        if (previous !== undefined && coupon.businessDaysFromPeriodStart <= previous) context.addIssue({code: "custom", path: ["series", index, "couponDates"], message: `${series.id}: coupon ${coupon.date} sits at ${coupon.businessDaysFromPeriodStart} business days, not after the previous coupon of ${period.id} at ${previous}; positions inside a period must advance`});
